          </B.Th>
          <B.Td>
            <div class="shw-component-advanced-table-cell-content-div">
              <HdsIcon @name={{B.data.icon}} @isInline={{true}} />
              {{B.data.album}}
            </div>
          </B.Td>
          <B.Td>
            <HdsBadge @text={{B.data.year}} @color={{B.data.badge-color}} />
          </B.Td>
          <B.Td>
            <HdsButtonSet>
              <HdsButton
                @text="Show more buttons"
