      {{#if this.hasValidation}}
        <F.CharacterCount @maxLength={{20}} />
        {{#if this.isInvalid}}
          <F.Error>Maximum numbers of characters exceeded</F.Error>
        {{/if}}
      {{else}}
        {{yield
          (hash
            CharacterCount=F.CharacterCount
            Error=F.Error
