interface GroupedOption {
  groupName: string;
  options: (string | GroupedOption)[];
}

const OPTIONS = ['Option 1', 'Option 2', 'Option 3'];

const CLUSTER_SIZE_OPTIONS = [
  {
    size: 'Extra Small',
    description: '2 vCPU | 1 GiB RAM',
    price: '$0.02',
  },
  {
    size: 'Small',
    description: '2 vCPU | 2 GiB RAM',
